//! Boot-time migration runner (issue #756).
//! Generated by codegraph-gate. DO NOT EDIT.
//!
//! The CLI-less fallback used to run the always-generated SeaORM `migration`
//! crate on every boot. Its tracking table (`seaql_migrations`) is invisible
//! to the ops harness band and to the admin-CLI engine, so a boot over an
//! already-migrated database re-applied every file — and the second pass of
//! the codelist seeds died on the #700 `set_org_id_from_session` trigger
//! (no session organization at boot ⇒ the zero tenant rewrites to NULL).
//!
//! This runner uses the ONE tracking table every plane shares:
//!
//! 
//! `platform._migrations` (`name`, `checksum`, `applied_at`).
//! 
//!
//! * `name` is the full migration filename (the SeaORM `MigrationName`
//!   convention, so an old `seaql_migrations` band is adoptable verbatim);
//! * `checksum` is the FNV-1a 64-bit hex digest of the ORIGINAL file bytes,
//!   computed inline (no extra dependency);
//! * a tracked file whose checksum changed is a HARD, NAMED error — a
//!   changed file is never silently re-applied over an existing band.
//!
//! Adoption (only when the tracking table is absent or empty, BEFORE
//! anything is applied): (1) `seaql_migrations` rows, (2) legacy
//! `schema_migrations` rows (the old admin-CLI band records the filename
//! without `.sql`), (3) for raw old harness bands, an object-existence
//! probe per file — the table/type/function/schema/extension the file
//! creates (or the table a seed/ALTER/INDEX/TRIGGER/POLICY/GRANT file
//! targets) already exists. Unrecognized files are NOT adopted: they apply,
//! and a genuinely incompatible raw band fails loudly. Adopted rows record
//! the CURRENT checksum, so drift is detectable from then on.

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

use sea_orm::{ConnectionTrait, DatabaseBackend, DatabaseConnection, Statement, TransactionTrait};

/// Advisory lock shared with the ops harness band
/// (`codegraph_ops::migrate::MIGRATION_LOCK_KEY`) so concurrent migration
/// runs serialise.
const ADVISORY_LOCK_KEY: i64 = 73287328;


const BACKEND: DatabaseBackend = DatabaseBackend::Postgres;
const TRACKING_TABLE: &str = "platform._migrations";
const CREATE_TRACKING_SQL: &str = "CREATE SCHEMA IF NOT EXISTS platform;\n\
CREATE TABLE IF NOT EXISTS platform._migrations (\
name TEXT PRIMARY KEY, \
checksum TEXT NOT NULL, \
applied_at TIMESTAMPTZ NOT NULL DEFAULT now()\
)";


/// Apply every untracked migration file, then record it. Idempotent: a second
/// boot over the same band applies nothing.
pub async fn run_boot_migrations(
    db: &DatabaseConnection,
) -> Result<(), Box<dyn std::error::Error>> {
    let dir = migrations_dir();
    if !dir.is_dir() {
        println!(
            "boot-migrations: no migrations/ directory found (tried {}); nothing to apply",
            dir.display()
        );
        return Ok(());
    }
    let files = collect_migrations(&dir)?;

    advisory_lock(db).await?;
    let result = apply(db, &files).await;
    if let Err(e) = advisory_unlock(db).await {
        if result.is_ok() {
            return Err(format!("boot-migrations: advisory unlock failed: {e}").into());
        }
        eprintln!("boot-migrations: advisory unlock failed: {e}");
    }
    result
}

async fn apply(
    db: &DatabaseConnection,
    files: &[(String, PathBuf)],
) -> Result<(), Box<dyn std::error::Error>> {
    let tracking_preexisted = tracking_table_exists(db).await?;
    let tracked: HashMap<String, String> = if tracking_preexisted {
        load_tracking(db).await?
    } else {
        HashMap::new()
    };

    // Adoption happens FIRST, before this runner creates any object: on a
    // database that has never run this runner, the absence of
    // `platform._migrations` is itself evidence that a legacy band applied
    // the files.
    let adopted: Vec<(String, String)> = if tracked.is_empty() {
        let mut adopted = Vec::new();
        for name in adopt_from_legacy_tables(db, files).await? {
            if let Some((_, path)) = files.iter().find(|(fname, _)| *fname == name) {
                adopted.push((name, fnv1a_64_hex(&std::fs::read(path)?)));
            }
        }
        for name in probe_existing_objects(db, files, &adopted, tracking_preexisted).await? {
            if let Some((_, path)) = files.iter().find(|(fname, _)| *fname == name) {
                adopted.push((name, fnv1a_64_hex(&std::fs::read(path)?)));
            }
        }
        adopted
    } else {
        Vec::new()
    };

    db.execute_unprepared(CREATE_TRACKING_SQL).await?;
    if !adopted.is_empty() {
        insert_tracking(db, &adopted).await?;
        println!(
            "boot-migrations: adopted {} already-applied file(s) from a legacy band",
            adopted.len()
        );
    }

    let adopted_names: HashSet<&str> = adopted.iter().map(|(name, _)| name.as_str()).collect();

    // Pass 1 — validate every tracked file BEFORE applying anything. A changed
    // file is a hard, named error; it must never be re-applied.
    for (name, path) in files {
        let Some(recorded) = tracked.get(name) else {
            continue;
        };
        let current = fnv1a_64_hex(&std::fs::read(path)?);
        if *recorded != current {
            return Err(format!(
                "boot-migrations: checksum mismatch for {name}: recorded {recorded}, current \
                 {current} — the file changed after it was applied; refusing to re-apply it over \
                 an existing migration band"
            )
            .into());
        }
    }

    // Pass 2 — apply untracked, unadopted files in filename order.
    let mut applied = 0usize;
    let mut already = 0usize;
    for (name, path) in files {
        if tracked.contains_key(name) || adopted_names.contains(name.as_str()) {
            already += 1;
            continue;
        }
        let bytes = std::fs::read(path)?;
        let checksum = fnv1a_64_hex(&bytes);
        let sql = String::from_utf8_lossy(&bytes).into_owned();

        let txn = db.begin().await?;
        if !sql.trim().is_empty() {
            if let Err(e) = txn.execute_unprepared(&sql).await {
                return Err(format!("boot-migrations: applying {name} failed: {e}").into());
            }
        }
        txn.execute_unprepared(&format!(
            "INSERT INTO {TRACKING_TABLE} (name, checksum) VALUES ('{}', '{}')",
            escape_sql(name),
            escape_sql(&checksum)
        ))
        .await?;
        txn.commit().await?;
        applied += 1;
    }

    println!("boot-migrations: {applied} applied, {already} already applied");
    Ok(())
}

/// Tier 1 + tier 2: names recorded by an older tracker. Returns the filenames
/// (from `files`) the legacy tables vouch for.
async fn adopt_from_legacy_tables(
    db: &DatabaseConnection,
    files: &[(String, PathBuf)],
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut adopted = Vec::new();

    // Tier 1: the always-generated SeaORM migration crate. `version` is the
    // full filename (RawSqlMigration::name).
    if table_exists(db, "seaql_migrations").await? {
        let versions = select_versions(db, "seaql_migrations").await?;
        for (name, _) in files {
            if versions.contains(name) {
                adopted.push(name.clone());
            }
        }
    }

    // Tier 2: the old admin-CLI engine. Its `version` is the filename without
    // `.sql`; accept both spellings so a hand-repaired band still adopts.
    if table_exists(db, "schema_migrations").await? {
        let versions = select_versions(db, "schema_migrations").await?;
        for (name, _) in files {
            if adopted.contains(name) {
                continue;
            }
            let stem = name.trim_end_matches(".sql");
            if versions.contains(name) || versions.contains(stem) {
                adopted.push(name.clone());
            }
        }
    }

    Ok(adopted)
}

async fn select_versions(
    db: &DatabaseConnection,
    table: &str,
) -> Result<HashSet<String>, Box<dyn std::error::Error>> {
    let rows = db
        .query_all_raw(Statement::from_string(
            BACKEND,
            format!("SELECT version FROM {table}"),
        ))
        .await?;
    let mut out = HashSet::new();
    for row in rows {
        let version: String = row.try_get("", "version")?;
        out.insert(version);
    }
    Ok(out)
}

/// Tier 3: object-existence probe for raw bands (harness runs that recorded
/// nothing). One catalog read
/// answers every probe, so a 130-file band costs one round trip.
async fn probe_existing_objects(
    db: &DatabaseConnection,
    files: &[(String, PathBuf)],
    already_adopted: &[(String, String)],
    tracking_preexisted: bool,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {

#[derive(Clone, Copy, PartialEq, Eq)]
enum CatalogKind {
    Table,
    Type,
    Function,
}

struct ObjectCatalog {
    namespaces: HashSet<String>,
    extensions: HashSet<String>,
    tables: HashSet<String>,
    types: HashSet<String>,
    functions: HashSet<String>,
}

impl ObjectCatalog {
    fn has(&self, kind: &CatalogKind, schema: &str, name: &str) -> bool {
        let key = format!("{schema}.{name}");
        match kind {
            CatalogKind::Table => self.tables.contains(&key),
            CatalogKind::Type => self.types.contains(&key),
            CatalogKind::Function => self.functions.contains(&key),
        }
    }
}


async fn load_object_catalog(
    db: &DatabaseConnection,
) -> Result<ObjectCatalog, Box<dyn std::error::Error>> {
    let sql = "SELECT 'namespace' AS kind, nspname AS name FROM pg_namespace \
               UNION ALL SELECT 'extension', extname FROM pg_extension \
               UNION ALL SELECT 'table', n.nspname || '.' || c.relname \
                   FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace \
                   WHERE c.relkind IN ('r', 'p') \
               UNION ALL SELECT 'type', n.nspname || '.' || t.typname \
                   FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace \
                   WHERE t.typtype IN ('c', 'd', 'e', 'r') \
               UNION ALL SELECT 'function', n.nspname || '.' || p.proname \
                   FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace";
    let rows = db
        .query_all_raw(Statement::from_string(BACKEND, sql))
        .await?;
    let mut catalog = ObjectCatalog {
        namespaces: HashSet::new(),
        extensions: HashSet::new(),
        tables: HashSet::new(),
        types: HashSet::new(),
        functions: HashSet::new(),
    };
    for row in rows {
        let kind: String = row.try_get("", "kind")?;
        let name: String = row.try_get("", "name")?;
        match kind.as_str() {
            "namespace" => {
                catalog.namespaces.insert(name);
            }
            "extension" => {
                catalog.extensions.insert(name);
            }
            "table" => {
                catalog.tables.insert(name);
            }
            "type" => {
                catalog.types.insert(name);
            }
            "function" => {
                catalog.functions.insert(name);
            }
            _ => {}
        }
    }
    Ok(catalog)
}


/// The object a migration file is anchored on. Raw bands are recognised by
/// "the thing this file creates (or targets) already exists".
enum AnchorKind {
    Namespace,
    Extension,
    Type,
    Function,
    Table,
}

struct Anchor {
    kind: AnchorKind,
    schema: String,
    name: String,
}

impl Anchor {
    /// A schema-qualified object (`common.widget`, `platform.fn`).
    fn qualified(kind: AnchorKind, token: &str) -> Self {
        let (schema, name) = split_identifier(token);
        Self { kind, schema, name }
    }

    /// A bare catalog name (a schema or an extension).
    fn bare(kind: AnchorKind, token: &str) -> Self {
        Self {
            kind,
            schema: clean_identifier(token),
            name: String::new(),
        }
    }
}

/// Classify a file by the FIRST recognised DDL statement. Unrecognised files
/// return `None` and are never adopted (they apply, and a genuinely
/// incompatible band fails loudly instead of being silently half-adopted).
///
/// The probe only needs the generated templates' own statement shapes; it
/// deliberately does not try to be a SQL parser.
fn first_anchor(sql: &str) -> Option<Anchor> {
    let lines: Vec<&str> = sql.lines().collect();
    // An extension alone is weak evidence: extension control files are
    // cluster-wide and images preinstall pgcrypto/uuid-ossp/pg_tle/pgmq, so a
    // fresh database can carry one without this file ever running. Prefer any
    // object the file itself defines, and fall back to the extension only for
    // a pure extension-install file (where re-applying is an idempotent
    // no-op anyway).
    let mut extension: Option<Anchor> = None;
    for (index, line) in lines.iter().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with("--") {
            continue;
        }
        let upper = trimmed.to_ascii_uppercase();
        if let Some(name) = after_keyword(&upper, trimmed, "CREATE SCHEMA") {
            return Some(Anchor::bare(AnchorKind::Namespace, &name));
        }
        if let Some(name) = after_keyword(&upper, trimmed, "CREATE EXTENSION") {
            if extension.is_none() {
                extension = Some(Anchor::bare(AnchorKind::Extension, &name));
            }
            continue;
        }
        if let Some(name) = after_keyword(&upper, trimmed, "CREATE TYPE")
            .or_else(|| after_keyword(&upper, trimmed, "CREATE DOMAIN"))
        {
            return Some(Anchor::qualified(AnchorKind::Type, &name));
        }
        if upper.starts_with("CREATE OR REPLACE FUNCTION")
            || upper.starts_with("CREATE OR REPLACE PROCEDURE")
            || upper.starts_with("CREATE FUNCTION")
            || upper.starts_with("CREATE PROCEDURE")
        {
            if let Some(name) = create_name_before_paren(trimmed) {
                return Some(Anchor::qualified(AnchorKind::Function, &name));
            }
        }
        if let Some(name) = after_keyword(&upper, trimmed, "CREATE TABLE")
            .or_else(|| after_keyword(&upper, trimmed, "CREATE UNLOGGED TABLE"))
            .or_else(|| after_keyword(&upper, trimmed, "CREATE TEMP TABLE"))
        {
            return Some(Anchor::qualified(AnchorKind::Table, &name));
        }
        if let Some(name) = after_keyword(&upper, trimmed, "INSERT INTO")
            .or_else(|| after_keyword(&upper, trimmed, "ALTER TABLE"))
        {
            return Some(Anchor::qualified(AnchorKind::Table, &name));
        }
        if upper.starts_with("CREATE UNIQUE INDEX")
            || upper.starts_with("CREATE INDEX")
            || upper.starts_with("CREATE TRIGGER")
            || upper.starts_with("CREATE POLICY")
        {
            // Generated triggers wrap `ON <table>` onto the next line, so look
            // a short window ahead rather than only at this line.
            let window = lines[index..lines.len().min(index + 8)].join(" ");
            let window_upper = window.to_ascii_uppercase();
            if let Some(pos) = window_upper.find(" ON ") {
                if let Some(name) = token_after(&window[pos + 4..]) {
                    return Some(Anchor::qualified(AnchorKind::Table, &name));
                }
            }
            continue;
        }
        if upper.starts_with("GRANT ") {
            if let Some(name) = grant_target(trimmed) {
                return Some(Anchor::qualified(AnchorKind::Table, &name));
            }
        }
    }
    extension
}

fn clean_identifier(raw: &str) -> String {
    raw.chars()
        .filter(|c| *c != '"' && *c != '`' && *c != '[' && *c != ']')
        .collect()
}

fn split_identifier(raw: &str) -> (String, String) {
    let cleaned = clean_identifier(raw);
    match cleaned.split_once('.') {
        Some((schema, name)) if !name.is_empty() => (schema.to_string(), name.to_string()),
        _ => ("public".to_string(), cleaned),
    }
}

fn token_after(rest: &str) -> Option<String> {
    let token: String = rest
        .trim_start()
        .chars()
        .take_while(|c| {
            c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-' | '@' | '"' | '`')
        })
        .collect();
    if token.is_empty() {
        None
    } else {
        Some(token)
    }
}

/// The identifier following a prefix keyword (after an optional
/// `IF [NOT] EXISTS` / `ONLY` clause).
fn after_keyword(upper: &str, original: &str, keyword: &str) -> Option<String> {
    if !upper.starts_with(keyword) {
        return None;
    }
    token_after(strip_if_exists(&original[keyword.len()..]))
}

/// `CREATE OR REPLACE FUNCTION` / `CREATE FUNCTION` → the name before `(`.
fn create_name_before_paren(line: &str) -> Option<String> {
    let open = line.find('(')?;
    let head = &line[..open];
    let tail = head
        .rsplit_once(|c: char| c.is_whitespace())
        .map(|(_, t)| t)
        .unwrap_or(head);
    if tail.is_empty() {
        None
    } else {
        Some(tail.to_string())
    }
}

/// `GRANT SELECT ON TABLE common.x TO app_user` / `GRANT ... ON common.x`.
fn grant_target(line: &str) -> Option<String> {
    let upper = line.to_ascii_uppercase();
    let idx = upper.find(" ON ")?;
    let rest = strip_if_exists(line[idx + 4..].trim_start());
    let rest_upper = rest.to_ascii_uppercase();
    if rest_upper.starts_with("ALL ")
        || rest_upper.starts_with("SCHEMA ")
        || rest_upper.starts_with("SEQUENCE ")
        || rest_upper.starts_with("FUNCTION ")
    {
        return None;
    }
    let rest = if rest_upper.starts_with("TABLE ") {
        &rest["TABLE ".len()..]
    } else {
        rest
    };
    token_after(rest)
}

fn strip_if_exists(rest: &str) -> &str {
    let trimmed = rest.trim_start();
    let upper = trimmed.to_ascii_uppercase();
    for prefix in ["IF NOT EXISTS ", "IF EXISTS ", "ONLY ", "CONCURRENTLY "] {
        if upper.starts_with(prefix) {
            return strip_if_exists(&trimmed[prefix.len()..]);
        }
    }
    trimmed
}

    if files.is_empty() {
        return Ok(Vec::new());
    }
    let catalog = load_object_catalog(db).await?;
    let mut adopted = Vec::new();
    for (name, path) in files {
        if already_adopted.iter().any(|(n, _)| n == name) {
            continue;
        }
        let Ok(sql) = std::fs::read_to_string(path) else {
            continue;
        };
        let Some(anchor) = first_anchor(&sql) else {
            continue;
        };
        let present = match anchor.kind {
            AnchorKind::Namespace => {
                // `platform` may exist because THIS runner is about to create
                // its tracking table there; only trust it when the tracking
                // table did not pre-exist.
                if anchor.schema == "platform" && tracking_preexisted {
                    false
                } else {
                    catalog.namespaces.contains(&anchor.schema)
                }
            }
            AnchorKind::Extension => catalog.extensions.contains(&anchor.schema),
            AnchorKind::Type => catalog.has(&CatalogKind::Type, &anchor.schema, &anchor.name),
            AnchorKind::Function => {
                catalog.has(&CatalogKind::Function, &anchor.schema, &anchor.name)
            }
            AnchorKind::Table => catalog.has(&CatalogKind::Table, &anchor.schema, &anchor.name),
        };
        if present {
            adopted.push(name.clone());
        }
    }
    Ok(adopted)

}


/// FNV-1a 64-bit hex (16 lowercase hex chars) over the ORIGINAL file bytes.
/// Inline by design: generated apps take no dependency for this.
fn fnv1a_64_hex(bytes: &[u8]) -> String {
    let mut hash: u64 = 0xcbf29ce484222325;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn escape_sql(value: &str) -> String {
    value.replace('\'', "''")
}

async fn tracking_table_exists(
    db: &DatabaseConnection,
) -> Result<bool, Box<dyn std::error::Error>> {

    let rows = db
        .query_all_raw(Statement::from_string(
            BACKEND,
            "SELECT to_regclass('platform._migrations') IS NOT NULL AS present",
        ))
        .await?;
    let present: bool = rows
        .first()
        .map(|row| row.try_get("", "present"))
        .transpose()?
        .unwrap_or(false);
    Ok(present)

}

async fn table_exists(
    db: &DatabaseConnection,
    table: &str,
) -> Result<bool, Box<dyn std::error::Error>> {

    let rows = db
        .query_all_raw(Statement::from_sql_and_values(
            BACKEND,
            "SELECT to_regclass($1) IS NOT NULL AS present",
            [table.into()],
        ))
        .await?;
    let present: bool = rows
        .first()
        .map(|row| row.try_get("", "present"))
        .transpose()?
        .unwrap_or(false);
    Ok(present)

}

async fn load_tracking(
    db: &DatabaseConnection,
) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let rows = db
        .query_all_raw(Statement::from_string(
            BACKEND,
            format!("SELECT name, checksum FROM {TRACKING_TABLE}"),
        ))
        .await?;
    let mut out = HashMap::new();
    for row in rows {
        let name: String = row.try_get("", "name")?;
        let checksum: String = row.try_get("", "checksum")?;
        out.insert(name, checksum);
    }
    Ok(out)
}

async fn insert_tracking(
    db: &DatabaseConnection,
    entries: &[(String, String)],
) -> Result<(), Box<dyn std::error::Error>> {
    if entries.is_empty() {
        return Ok(());
    }
    let values: Vec<String> = entries
        .iter()
        .map(|(name, checksum)| {
            format!("('{}', '{}')", escape_sql(name), escape_sql(checksum))
        })
        .collect();
    db.execute_unprepared(&format!(
        "INSERT INTO {TRACKING_TABLE} (name, checksum) VALUES {} \
         ON CONFLICT (name) DO NOTHING",
        values.join(", ")
    ))
    .await?;
    Ok(())
}

async fn advisory_lock(db: &DatabaseConnection) -> Result<(), Box<dyn std::error::Error>> {

    db.execute_unprepared(&format!("SELECT pg_advisory_lock({ADVISORY_LOCK_KEY})"))
        .await?;
    Ok(())

}

async fn advisory_unlock(db: &DatabaseConnection) -> Result<(), Box<dyn std::error::Error>> {

    db.execute_unprepared(&format!("SELECT pg_advisory_unlock({ADVISORY_LOCK_KEY})"))
        .await?;
    Ok(())

}

/// Locate the raw SQL migrations directory.
///
/// Resolution order (identical to the retired SeaORM fallback, so an existing
/// deployment keeps finding its files):
/// 1. `MIGRATIONS_DIR` environment variable
/// 2. `<repo>/migrations` (derived from this crate's manifest dir — the app
///    crate lives at `<repo>/generated/<app>`, so `../../migrations` resolves
///    to the repo root)
/// 3. `./migrations` relative to the current working directory
fn migrations_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("MIGRATIONS_DIR") {
        let p = Path::new(&dir);
        if p.exists() {
            return p.to_path_buf();
        }
    }
    let manifest_relative = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("migrations");
    if manifest_relative.exists() {
        return manifest_relative;
    }
    Path::new("migrations").to_path_buf()
}

/// Every `.sql` file in filename order.
fn collect_migrations(
    dir: &Path,
) -> Result<Vec<(String, PathBuf)>, Box<dyn std::error::Error>> {
    let mut entries: Vec<PathBuf> = std::fs::read_dir(dir)?
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "sql"))
        .collect();
    entries.sort_by_key(|path| path.file_name().map(|n| n.to_os_string()));
    let mut files = Vec::new();
    for path in entries {
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();
        if name.is_empty() {
            continue;
        }
        files.push((name, path));
    }
    Ok(files)
}
